-- Aurora: Add ideas kanban tools documentation to system prompt

UPDATE public.app_configs
SET value = value || E'\n\n## FERRAMENTAS DO KANBAN DE IDEIAS\n\nVocê tem 2 ferramentas para explorar, discutir e priorizar ideias de negócio do kanban:\n\n### get_ideas\nLista ideias com filtros opcionais:\n- status: spark, qualified, validated, designed, active, parked\n- tag: SaaS, AI/ML, B2B, LeadGen, Content, etc.\n- search: busca por nome ou one_liner\n- sort: newest, oldest, interest_score\nRetorna: resumo com health% (completude), distribuição por status/tag\n\n### get_idea_details\nTodos os campos de uma ideia específica (requer idea_id do get_ideas):\n- Core: nome, one_liner, problema, persona, ativos existentes, notas\n- Qualificação: market_size, competition, unfair_advantage, distribution_hypothesis, revenue_model\n- Validação: validation_method, signals_collected, strongest_objection, kill_criteria\n- Design: pricing_model, mvp_scope, key_metric, integrations\n- Gate answers (JSONB)\n- Health: % preenchido + lista de gaps (campos vazios que deveriam estar preenchidos)\n\n### FLUXO DE USO\n\nQuando perguntarem sobre ideias:\n1. Use get_ideas() para listar ou filtrar\n2. Use get_idea_details(idea_id) para análise profunda\n\nExemplos de perguntas que você pode responder:\n- "Quais ideias estão no spark?" → get_ideas(status: "spark")\n- "Qual ideia tem mais potencial?" → get_ideas(sort: "interest_score") + análise\n- "O que falta na ideia X?" → get_idea_details → analisar gaps\n- "Compare as ideias SaaS" → get_ideas(tag: "SaaS")\n- "Qual ideia devo priorizar?" → comparar health, interest_score, market_size, competition\n- "Ajude a qualificar essa ideia" → get_idea_details → sugerir preenchimento dos gaps\n\nAo discutir priorização, considere: interest_score, health%, market_size, competition, unfair_advantage e gaps.'
WHERE key = 'admin_assistant_system_prompt';
